#!/usr/bin/env python3
"""Structural validator for a 50-prompt suite generated by sophisticated-prompt-generator."""

import re
import sys
from pathlib import Path

REQUIRED_TOPICS = 10
PROMPTS_PER_TOPIC = 5
TOTAL_PROMPTS = 50

def validate(path: Path) -> list[str]:
    errors = []
    text = path.read_text(encoding="utf-8")

    # Count topics
    topic_headers = re.findall(r"^## Topic \d+ —", text, re.MULTILINE)
    if len(topic_headers) != REQUIRED_TOPICS:
        errors.append(f"Expected {REQUIRED_TOPICS} topics, found {len(topic_headers)}")

    # Count prompt blocks (### Prompt X.Y)
    prompt_headers = re.findall(r"^### Prompt \d+\.\d+", text, re.MULTILINE)
    if len(prompt_headers) != TOTAL_PROMPTS:
        errors.append(f"Expected {TOTAL_PROMPTS} prompts, found {len(prompt_headers)}")

    # Success checks
    success_checks = re.findall(r"\*\*Success check:\*\*", text)
    if len(success_checks) < TOTAL_PROMPTS:
        errors.append(f"Expected at least {TOTAL_PROMPTS} Success checks, found {len(success_checks)}")

    # Topic 10 must exist and mention debug/audit
    if not re.search(r"## Topic 10 —.*(Debug|Audit|Meta)", text, re.IGNORECASE):
        errors.append("Topic 10 must be the Debug/Audit/Meta topic")

    # Axes annotations recommended
    axes_count = len(re.findall(r"\*\*Axes:\*\*", text))
    if axes_count < TOTAL_PROMPTS * 0.8:
        errors.append(f"Too few Axes annotations ({axes_count}); expected near {TOTAL_PROMPTS}")

    # Basic completeness
    if "Generation Metadata" not in text and "Seed" not in text:
        errors.append("Missing generation metadata / seed restatement")

    return errors

def main():
    if len(sys.argv) != 2:
        print("Usage: validate_suite.py <path-to-suite.md>", file=sys.stderr)
        sys.exit(2)
    path = Path(sys.argv[1])
    if not path.is_file():
        print(f'{{"error":"file not found: {path}"}}', file=sys.stderr)
        sys.exit(3)
    errors = validate(path)
    if errors:
        print("FAIL")
        for e in errors:
            print(f"  - {e}")
        sys.exit(1)
    print("PASS")
    print(f"  Topics: {REQUIRED_TOPICS}")
    print(f"  Prompts: {TOTAL_PROMPTS}")
    print("  Success checks present")
    print("  Topic 10 is Debug/Audit/Meta")
    sys.exit(0)

if __name__ == "__main__":
    main()
